import java.util.*;

class Solution {
  public boolean canCross(int[] stones) {
    Map<Integer, Set<Integer>> jumps = new HashMap<>(); // stone -> jump sizes that can land on it
    for (int s : stones) jumps.put(s, new HashSet<>());
    jumps.get(stones[0]).add(0);
    for (int s : stones) {
      for (int k : jumps.get(s)) {
        for (int step = k - 1; step <= k + 1; step++) {
          if (step <= 0) continue;
          Set<Integer> target = jumps.get(s + step);
          if (target != null) target.add(step);
        }
      }
    }
    return !jumps.get(stones[stones.length - 1]).isEmpty();
  }
}
